-- PostgreSQL plpgsql translations of the Oracle procedures.
-- Transaction control: the procedures run inside the caller's transaction.
-- Oracle's explicit COMMIT/ROLLBACK are replaced by that transaction and by the
-- implicit savepoint of the plpgsql EXCEPTION block. (Postgres rejects COMMIT
-- in a block that has an EXCEPTION section, and rejects it when CALL is issued
-- inside an explicit transaction.)

CREATE OR REPLACE PROCEDURE sp_customer_tier()
LANGUAGE plpgsql
AS $$
DECLARE
    rec      record;
    v_tier   varchar(20);
    v_status varchar(20);
BEGIN
    DELETE FROM customer_tiers;

    FOR rec IN
        SELECT o.customer_id,
               c.customer_name,
               SUM(o.order_total) AS total_spend,
               COUNT(*)           AS order_count
        FROM   orders o
        JOIN   customers c ON c.customer_id = o.customer_id
        WHERE  COALESCE(c.status, 'ACTIVE') = 'ACTIVE'
        GROUP  BY o.customer_id, c.customer_name
        ORDER  BY total_spend, o.customer_id
    LOOP
        IF rec.total_spend >= 1000 THEN
            v_tier := 'GOLD';
        ELSIF rec.total_spend >= 500 THEN
            v_tier := 'SILVER';
        ELSE
            v_tier := 'BRONZE';
        END IF;

        INSERT INTO customer_tiers
            (customer_id, customer_name, total_spend, order_count, tier, computed_at)
        VALUES
            (rec.customer_id, rec.customer_name, rec.total_spend, rec.order_count,
             v_tier, now());
    END LOOP;

    -- Oracle row-limit predicate replaced by LIMIT 1.
    -- (STRICT keeps Oracle's NO_DATA_FOUND behaviour on an empty table.)
    SELECT status INTO STRICT v_status FROM customers LIMIT 1;
END;
$$;

CREATE OR REPLACE PROCEDURE sp_monthly_report(p_month varchar)
LANGUAGE plpgsql
AS $$
DECLARE
    rec        record;
    v_row      monthly_report;          -- composite row-type variable
    v_has_data numeric := 0;
BEGIN
    -- Oracle counted one row from its dummy table; that is always 1.
    v_has_data := 1;

    DELETE FROM monthly_report WHERE report_month = p_month;

    FOR rec IN
        SELECT p.category                                     AS category,
               COALESCE(SUM(oi.quantity * oi.unit_price), 0)  AS revenue,
               COALESCE(SUM(oi.quantity), 0)                  AS units_sold
        FROM   order_items oi
        JOIN   products p ON p.product_id = oi.product_id
        GROUP  BY p.category
        ORDER  BY revenue DESC, p.category
    LOOP
        v_row.report_month := p_month;
        v_row.category     := rec.category;
        v_row.revenue      := rec.revenue;
        v_row.units_sold   := rec.units_sold;

        INSERT INTO monthly_report
            (report_month, category, revenue, units_sold)
        VALUES
            (v_row.report_month, v_row.category, v_row.revenue, v_row.units_sold);
    END LOOP;

    IF v_has_data = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'e_no_data';
    END IF;
EXCEPTION
    WHEN SQLSTATE 'P0002' THEN
        -- e_no_data: work done in this block is rolled back by the implicit
        -- savepoint; swallow the error as Oracle's handler did.
        NULL;
    WHEN OTHERS THEN
        -- Block's changes are rolled back automatically; re-raise.
        RAISE;
END;
$$;
